<script>
(function(){
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- scramble decode ---- */
  var GLYPHS = "▮§#%&?$@≠*+·";
  function scramble(el, text, dur){
    if (rm){ el.textContent = text; return; }
    dur = dur || 950;
    var start = null;
    function frame(now){
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / dur);
      var settled = Math.floor(p * text.length);
      var out = "";
      for (var i = 0; i < text.length; i++){
        var ch = text.charAt(i);
        if (i < settled || ch === " ") out += ch;
        else out += GLYPHS.charAt((Math.random() * GLYPHS.length) | 0);
      }
      el.textContent = out;
      if (p < 1) requestAnimationFrame(frame); else el.textContent = text;
    }
    requestAnimationFrame(frame);
  }
  var titleEl = document.querySelector('[data-scramble]');
  if (titleEl){ var t = titleEl.textContent; setTimeout(function(){ scramble(titleEl, t, 1100); }, 200); }

  /* ---- reveal on view ---- */
  var io = new IntersectionObserver(function(es){
    es.forEach(function(e){
      if (!e.isIntersecting) return;
      e.target.classList.add('in');
      var sv = e.target.querySelector('[data-scramble-view]');
      if (sv && !sv.dataset.done){ sv.dataset.done = "1"; scramble(sv, sv.textContent, 800); }
      io.unobserve(e.target);
    });
  }, { threshold: 0.12, rootMargin: "0px 0px -6% 0px" });
  document.querySelectorAll('.reveal').forEach(function(el){ io.observe(el); });

  /* ---- sticky rail: active item + progress ---- */
  var items = Array.prototype.slice.call(document.querySelectorAll('.entry'));
  var links = Array.prototype.slice.call(document.querySelectorAll('.toc a'));
  var rpLabel = document.getElementById('rpLabel');
  var rpVerses = document.getElementById('rpVerses');
  var rpFill = document.getElementById('rpFill');
  function pad(n){ return (n < 10 ? "0" : "") + n; }
  function setActive(i){
    links.forEach(function(a, j){ a.classList.toggle('active', j === i); });
    rpLabel.textContent = "Item " + pad(i + 1) + " / 25";
    rpVerses.textContent = pad(i + 1) + " settled";
    rpFill.style.width = ((i + 1) / items.length * 100) + "%";
  }
  function onScroll(){
    var mid = window.innerHeight * 0.42;
    var cur = 0;
    items.forEach(function(it, i){ if (it.getBoundingClientRect().top < mid) cur = i; });
    setActive(cur);
  }
  var ticking = false;
  window.addEventListener('scroll', function(){
    if (!ticking){ ticking = true; requestAnimationFrame(function(){ onScroll(); ticking = false; }); }
  }, { passive: true });
  onScroll();
  links.forEach(function(a, i){
    a.addEventListener('click', function(e){
      e.preventDefault();
      items[i].scrollIntoView({ behavior: rm ? 'auto' : 'smooth', block: 'start' });
    });
  });

  /* ---- stamp tilt on invoice (fine pointers only) ---- */
  var wrap = document.querySelector('.stamp-wrap');
  if (wrap && !rm && window.matchMedia('(pointer: fine)').matches){
    var inv = document.getElementById('invoice');
    inv.addEventListener('mousemove', function(e){
      var r = inv.getBoundingClientRect();
      var x = (e.clientX - r.left) / r.width - 0.5;
      var y = (e.clientY - r.top) / r.height - 0.5;
      wrap.style.transform = "translate(" + (x * 12) + "px," + (y * 12) + "px)";
    });
  }
})();
</script>
